const names=['Registro de Marcas','Gestão Estratégica de Portfólio de Marcas','Pesquisa de Viabilidade e Anterioridade','Registro de Patentes','Registro de Desenho Industrial','Direitos Autorais','Registro de Software','Proteção Internacional de Ativos Intelectuais','Monitoramento e Defesa de Direitos','Oposição, Recursos e Processos Administrativos','Contratos de Propriedade Intelectual','Contencioso em Propriedade Intelectual'];
const list=document.getElementById('service-list');
names.forEach((name,index)=>{const detail=document.createElement('details');detail.name='servicos';const summary=document.createElement('summary');summary.textContent=name;detail.append(summary);const content=document.createElement('div');content.className='service-content';window.legacyServices[index].forEach(item=>{if(Array.isArray(item)){const ul=document.createElement('ul');item.forEach(text=>{const li=document.createElement('li');li.textContent=text;ul.append(li)});content.append(ul)}else{const p=document.createElement('p');p.textContent=item;content.append(p)}});detail.append(content);list.append(detail)});
document.getElementById('contact-form').addEventListener('submit',event=>{event.preventDefault();const values=new FormData(event.currentTarget);const body=`Nome: ${values.get('nome')}\nTelefone: ${values.get('telefone')}\nEmail: ${values.get('email')}\n\n${values.get('mensagem')}`;window.location.href=`mailto:sejadonodamarca@gmail.com?subject=${encodeURIComponent('Contato pelo site Legacy')}&body=${encodeURIComponent(body)}`;});
